class ExplicitCodecSource final:public engine::assets::TensorSource{
 std::filesystem::path path_{"explicit-synthetic-oobleck-cpu"};std::map<std::string,std::vector<int64_t>>table_;
 void conv(const std::string&p,int64_t out,int64_t in,int64_t kernel,bool bias){table_[p+".weight"]={out,in,kernel};if(bias)table_[p+".bias"]={out};}
 void snake(const std::string&p,int64_t channels){table_[p+".alpha"]={channels};table_[p+".beta"]={channels};}
 void residual(const std::string&p,int64_t channels){snake(p+".layers.0",channels);conv(p+".layers.1",channels,channels,7,true);snake(p+".layers.2",channels);conv(p+".layers.3",channels,channels,1,true);}
public:
 size_t total_bytes=0;mutable size_t weight_reads=0;bool wn=false;
 ExplicitCodecSource(const engine::codecs::OobleckAudioVaeConfig&c,bool normalized=false):wn(normalized){std::vector<int64_t>channels{c.channels};for(auto m:c.c_mults)channels.push_back(c.channels*m);conv(c.encoder_prefix+".layers.0",channels[0],c.audio_channels,7,true);
 for(size_t i=0;i<c.strides.size();++i){auto p=c.encoder_prefix+".layers."+std::to_string(i+1);for(int r=0;r<3;++r)residual(p+".layers."+std::to_string(r),channels[i]);snake(p+".layers.3",channels[i]);conv(p+".layers.4",channels[i+1],channels[i],2*c.strides[i],true);}
 snake(c.encoder_prefix+".layers."+std::to_string(c.strides.size()+1),channels.back());conv(c.encoder_prefix+".layers."+std::to_string(c.strides.size()+2),c.encoder_latent_dim,channels.back(),3,true);
 conv(c.decoder_prefix+".layers.0",channels.back(),c.decoder_latent_dim,7,true);
 for(size_t i=0;i<c.strides.size();++i){size_t b=c.strides.size()-i;auto p=c.decoder_prefix+".layers."+std::to_string(i+1);snake(p+".layers.0",channels[b]);table_[p+".layers.1.weight"]={channels[b],channels[b-1],2*c.strides[b-1]};table_[p+".layers.1.bias"]={channels[b-1]};for(int r=2;r<5;++r)residual(p+".layers."+std::to_string(r),channels[b-1]);}
 snake(c.decoder_prefix+".layers."+std::to_string(c.strides.size()+1),channels.front());conv(c.decoder_prefix+".layers."+std::to_string(c.strides.size()+2),c.audio_channels,channels.front(),7,false);
 if(wn){auto original=table_;for(const auto&e:original)if(e.first.size()>=7&&e.first.substr(e.first.size()-7)==".weight"){table_.erase(e.first);std::string p=e.first.substr(0,e.first.size()-7);table_[p+".weight_v"]=e.second;table_[p+".weight_g"]={e.second[0],1,1};}}
 for(const auto&e:table_){size_t n=1;for(auto d:e.second)n*=size_t(d);total_bytes+=n*4;}}
 const std::filesystem::path&source_path()const noexcept override{return path_;}bool has_tensor(std::string_view n)const noexcept override{return table_.count(std::string(n));}
 engine::assets::TensorMetadata require_metadata(std::string_view n)const override{auto it=table_.find(std::string(n));if(it==table_.end())throw std::runtime_error("unknown explicit codec name: "+std::string(n));return {it->first,"F32",it->second};}
 std::vector<engine::assets::TensorMetadata>tensors()const override{std::vector<engine::assets::TensorMetadata>v;for(const auto&e:table_)v.push_back({e.first,"F32",e.second});return v;}
 std::vector<float>require_f32(std::string_view n,const std::optional<std::vector<int64_t>>&shape=std::nullopt)const override{++weight_reads;auto m=require_metadata(n);if(shape&&*shape!=m.shape)throw std::runtime_error("explicit codec shape mismatch");size_t count=1;for(auto d:m.shape)count*=size_t(d);if(count*4>16<<20)throw std::runtime_error("fixture array exceeds16MiB");std::vector<float>v(count);bool snake=std::string(n).find(".alpha")!=std::string::npos||std::string(n).find(".beta")!=std::string::npos;bool g=std::string(n).find(".weight_g")!=std::string::npos;for(size_t i=0;i<count;++i)v[i]=snake?(-.2F+float(i%3)/16):g?.2F:float(int((i*17+n.size()*7)%31)-15)/1024;return v;}
 std::optional<std::vector<float>>optional_f32(std::string_view n,const std::optional<std::vector<int64_t>>&shape=std::nullopt)const override{if(!has_tensor(n))return std::nullopt;return require_f32(n,shape);}
 engine::assets::RawTensorData require_tensor_data(std::string_view n)const override{auto m=require_metadata(n);auto values=require_f32(n);std::vector<std::byte>b(values.size()*4);std::memcpy(b.data(),values.data(),b.size());return {m,std::move(b)};}
 int64_t require_i64_scalar(std::string_view)const override{throw std::runtime_error("no scalar in codec fixture");}
};
inline engine::codecs::OobleckAudioVaeConfig tiny_codec(bool full=false){engine::codecs::OobleckAudioVaeConfig c;c.channels=2;c.c_mults=full?std::vector<int64_t>{1,1,1,1,1,1}:std::vector<int64_t>{1,2};c.strides=full?std::vector<int64_t>{2,2,4,4,5,6}:std::vector<int64_t>{2,3};c.encoder_latent_dim=full?128:4;c.decoder_latent_dim=full?64:2;return c;}
