 if(verify_nodes&&current_graph){while(node_cursor<size_t(ggml_graph_n_nodes(current_graph))){auto*n=ggml_graph_node(current_graph,int(node_cursor));if(n->op!=GGML_OP_NONE&&n->op!=GGML_OP_RESHAPE&&n->op!=GGML_OP_VIEW&&n->op!=GGML_OP_TRANSPOSE&&n->op!=GGML_OP_PERMUTE&&(n->flags&GGML_TENSOR_FLAG_COMPUTE))break;++node_cursor;}
 if(node_cursor<size_t(ggml_graph_n_nodes(current_graph))){auto*n=ggml_graph_node(current_graph,int(node_cursor));if(n->op==GGML_OP_MUL_MAT&&n->type==GGML_TYPE_F32&&n->src[0]->type==GGML_TYPE_F32&&n->src[1]->type==GGML_TYPE_F32&&ggml_is_contiguous(n)&&ggml_is_contiguous(n->src[0])&&ggml_is_contiguous(n->src[1])&&n->ne[2]==1&&n->ne[3]==1){auto*a=static_cast<const float*>(n->src[0]->data);auto*b=static_cast<const float*>(n->src[1]->data);auto*out=static_cast<const float*>(n->data);if(a&&b&&out&&out!=a&&out!=b){for(int64_t i=0;i<n->ne[0];++i)for(int64_t j=0;j<n->ne[1];++j){double expected=0;for(int64_t k=0;k<n->src[0]->ne[0];++k)expected+=double(a[i*n->src[0]->ne[0]+k])*b[j*n->src[1]->ne[0]+k];if(std::abs(out[j*n->ne[0]+i]-expected)>2e-6+2e-6*std::abs(expected))node_bad=true;}++verified_nodes;}}}++node_cursor;}
